3	use std::slice;
4	
5	use comemo::Tracked;
6	use ecow::{EcoString, EcoVec, eco_format, eco_vec};
7	use typst_syntax::{Span, Spanned};
8	
9	use crate::diag::{
10	    At, CallSpanned, SourceDiagnostic, SourceResult, StrResult, bail, error,
11	};
12	use crate::engine::Engine;
13	use crate::foundations::{
14	    Array, Context, Dict, FromValue, Func, IntoValue, Repr, Str, Value, cast, func, repr,
