324	#[scope]
325	impl Args {
326	    /// Constructs spreadable arguments in place.
327	    ///
328	    /// This function behaves like `{let arguments(..args) = args}`.
329	    ///
330	    /// ```example
331	    /// #let args = arguments(
332	    ///   stroke: red,
333	    ///   inset: 1em,
334	    ///   [Body],
335	    /// )
336	    /// #box(..args)
337	    /// ```
338	    #[func(constructor, since = "0.10.0")]
339	    pub fn construct(
340	        args: &mut Args,
341	        /// The arguments to construct.
342	        #[external]
343	        #[variadic]
344	        args_: Vec<Value>,
345	    ) -> Args {
346	        args.take()
347	    }
348	
349	    /// Returns the number of arguments, positional or named.
350	    ///
351	    /// ```example
352	    /// #arguments(a: "b", none, 1).len()
353	    /// ```
354	    #[func(title = "Length", since = "0.15.0")]
355	    pub fn len(&self) -> usize {
356	        self.items.len()
357	    }
358	
359	    /// Returns the positional argument at the specified index, or the named
360	    /// argument with the specified name.
361	    ///
362	    /// If the key is an @int, this is equivalent to first calling
363	    /// @arguments.pos[`pos`] and then @array.at. If it is a @str, this is
364	    /// equivalent to first calling @arguments.named[`named`] and then
365	    /// @dictionary.at.
366	    ///
367	    /// Named arguments can also be accessed with field syntax (e.g.
368	    /// `{arguments(key: 42).key}`) if no default is needed. Unlike
369	    /// @dictionary[dictionaries], fields on arguments cannot be modified.
370	    ///
371	    /// ```example
372	    /// #let args = arguments(1, x: 2, 3)
373	    /// #args.at(1) \
374	    /// #args.at("x") \
375	    /// #args.x
376	    /// ```
377	    #[func(since = "0.12.0")]
378	    pub fn at(
379	        &self,
380	        /// The index or name of the argument to get.
381	        key: ArgumentKey,
382	        /// A default value to return if the key is invalid.
383	        ///
384	        /// ```example
385	        /// #let args = arguments("hello")
386	        /// #args.at(0, default: "missing") \
387	        /// #args.at(1, default: "missing") \
388	        /// #args.at("a", default: "missing")
389	        /// ```
390	        #[named]
391	        default: Option<Value>,
392	    ) -> StrResult<Value> {
393	        self.get(&key)
394	            .cloned()
395	            .or(default)
396	            .ok_or_else(|| missing_key_no_default(key))
397	    }
398	
399	    /// Returns the positional arguments as an array.
400	    ///
401	    /// ```example
402	    /// #arguments(1, a: 2, "foo").pos()
403	    /// ```
404	    #[func(name = "pos", title = "Positional", since = "forever")]
405	    pub fn to_pos(&self) -> Array {
406	        self.items
407	            .iter()
408	            .filter(|item| item.name.is_none())
409	            .map(|item| item.value.v.clone())
410	            .collect()
411	    }
412	
413	    /// Returns the named arguments as a dictionary.
414	    ///
415	    /// ```example
416	    /// #arguments(1, a: 2, "foo").named()
417	    /// ```
418	    #[func(name = "named", since = "forever")]
419	    pub fn to_named(&self) -> Dict {
420	        self.items
421	            .iter()
422	            .filter_map(|item| item.name.clone().map(|name| (name, item.value.v.clone())))
423	            .collect()
424	    }
425	
426	    /// Produces a new `arguments` with only the arguments for which the value
427	    /// passes the test.
428	    ///
429	    /// ```example
430	    /// #{
431	    ///   arguments(-1, a: 0, b: 1, 2)
432	    ///     .filter(v => v > 0)
433	    /// }
434	    /// ```
435	    #[func(since = "0.15.0")]
436	    pub fn filter(
437	        self,
438	        engine: &mut Engine,
439	        context: Tracked<Context>,
440	        /// The function to apply to each value. Must return a boolean.
441	        test: Spanned<Func>,
442	    ) -> SourceResult<Args> {
443	        let mut run_test = |v: &Value| test.call::<bool>(engine, context, [v.clone()]);
444	        self.into_iter()
445	            .filter_map(|arg| {
446	                run_test(&arg.value.v).map(|b| b.then_some(arg)).transpose()
447	            })
448	            .collect()
449	    }
450	
451	    /// Produces a new `arguments` by transforming each argument value with the
452	    /// passed function.
453	    ///
454	    /// ```example
455	    /// #{
456	    ///   arguments(0, a: 1, 2)
457	    ///     .map(v => v + 1)
458	    /// }
459	    /// ```
460	    #[func(since = "0.15.0")]
461	    pub fn map(
462	        self,
463	        engine: &mut Engine,
464	        context: Tracked<Context>,
465	        /// The function to apply to each value.
466	        mapper: Spanned<Func>,
467	    ) -> SourceResult<Args> {
468	        self.into_iter()
469	            .map(|arg| {
470	                let mapped_value = mapper.call(engine, context, [arg.value.v])?;
471	                Ok(Arg {
472	                    span: arg.span,
473	                    name: arg.name,
474	                    value: Spanned::detached(mapped_value),
475	                })
476	            })
477	            .collect()
478	    }
479	}
