494	impl PartialEq for Args {
495	    fn eq(&self, other: &Self) -> bool {
496	        self.to_pos() == other.to_pos() && self.to_named() == other.to_named()
497	    }
498	}
499	
500	impl Add for Args {
501	    type Output = Self;
502	
503	    fn add(mut self, rhs: Self) -> Self::Output {
504	        self.items.retain(|item| {
505	            !item.name.as_ref().is_some_and(|name| {
506	                rhs.items.iter().any(|a| a.name.as_ref() == Some(name))
507	            })
508	        });
509	        self.items.extend(rhs.items);
510	        self.span = Span::detached();
511	        self
512	    }
513	}
514	
515	impl FromIterator<Arg> for Args {
516	    fn from_iter<T: IntoIterator<Item = Arg>>(iter: T) -> Self {
517	        Self {
518	            span: Span::detached(),
519	            items: iter.into_iter().collect(),
520	        }
521	    }
522	}
523	
524	impl IntoIterator for Args {
525	    type Item = Arg;
526	    type IntoIter = <EcoVec<Arg> as IntoIterator>::IntoIter;
527	
528	    fn into_iter(self) -> Self::IntoIter {
529	        self.items.into_iter()
530	    }
531	}
532	
533	impl<'a> IntoIterator for &'a Args {
534	    type Item = &'a Arg;
535	    type IntoIter = slice::Iter<'a, Arg>;
536	
537	    fn into_iter(self) -> Self::IntoIter {
538	        self.items.iter()
539	    }
540	}
