542	/// An argument to a function call: `12` or `draw: false`.
543	#[derive(Clone, Hash)]
544	pub struct Arg {
545	    /// The span of the whole argument.
546	    pub span: Span,
547	    /// The name of the argument (`None` for positional arguments).
548	    pub name: Option<Str>,
549	    /// The value of the argument.
550	    pub value: Spanned<Value>,
551	}
552	
553	impl Debug for Arg {
554	    fn fmt(&self, f: &mut Formatter) -> fmt::Result {
555	        if let Some(name) = &self.name {
556	            name.fmt(f)?;
557	            f.write_str(": ")?;
558	            self.value.v.fmt(f)
559	        } else {
560	            self.value.v.fmt(f)
561	        }
562	    }
563	}
564	
565	impl Repr for Arg {
566	    fn repr(&self) -> EcoString {
567	        if let Some(name) = &self.name {
568	            eco_format!("{}: {}", name, self.value.v.repr())
569	        } else {
570	            self.value.v.repr()
571	        }
572	    }
573	}
574	
575	impl PartialEq for Arg {
576	    fn eq(&self, other: &Self) -> bool {
577	        self.name == other.name && self.value.v == other.value.v
578	    }
579	}
580	
581	/// Things that can be used as arguments.
582	pub trait IntoArgs {
583	    /// Convert into arguments, attaching the `fallback` span in case `Self`
584	    /// doesn't have a span.
585	    fn into_args(self, fallback: Span) -> Args;
586	}
587	
588	impl IntoArgs for Args {
589	    fn into_args(self, fallback: Span) -> Args {
590	        self.spanned(fallback)
591	    }
592	}
593	
594	impl<I, T> IntoArgs for I
595	where
596	    I: IntoIterator<Item = T>,
597	    T: IntoValue,
598	{
599	    fn into_args(self, fallback: Span) -> Args {
600	        Args::new(fallback, self)
601	    }
602	}
603	
604	/// The missing key access error message when no default was given.
605	#[cold]
606	fn missing_key_no_default(key: ArgumentKey) -> EcoString {
607	    match key {
608	        ArgumentKey::Index(i) => eco_format!(
609	            "no positional argument at index {i} and no default value was specified",
610	        ),
611	        ArgumentKey::Name(name) => eco_format!(
612	            "no named argument {} and no default value was specified",
613	            name.repr()
614	        ),
615	    }
616	}
