179	/// Attempt to resolve a mutating method call by evaluating args and then
180	/// attempting to access the target mutably. If the target's type doesn't
181	/// support mutating methods (only Array/Dict actually do), returns the
182	/// evaluated value and arguments.
183	///
184	/// This currently causes a number of bad errors due to limitations of the
185	/// [`Access`] trait used for mutation.
186	fn maybe_resolve_mutating(
187	    vm: &mut Vm,
188	    target: ast::Expr,
189	    field: ast::Ident,
190	    args: ast::Args,
191	    span: Span,
192	) -> SourceResult<Result<Value, (Value, Args)>> {
193	    // We evaluate the arguments first because `target_expr.access(vm)` mutably
194	    // borrows `vm`, so we won't be able to call `args.eval(vm)` afterwards.
195	    let args = args.eval(vm)?.spanned(span);
196	    match target.access(vm)? {
197	        // Skip methods that aren't actually mutating for dictionaries.
198	        target @ Value::Dict(_) if !is_dict_mutating_method(field.as_str()) => {
199	            Ok(Err((target.clone(), args)))
200	        }
201	        // Only arrays and dictionaries have mutable methods.
202	        target @ (Value::Array(_) | Value::Dict(_)) => {
203	            let value = call_method_mut(target, &field, args, span);
204	            let point = || Tracepoint::call(field.get().clone());
205	            Ok(Ok(value.trace(vm.world(), point, span)?))
206	        }
207	        target => Ok(Err((target.clone(), args))),
208	    }
209	}
