398	/// If the value is content, the string "element" and the name of its element
399	/// function, or the string "type" and the name of the value's type.
400	fn element_or_type_with_name(value: &Value) -> (&'static str, &'static str) {
401	    if let Value::Content(content) = value {
402	        ("element", content.elem().name())
403	    } else {
404	        ("type", value.ty().long_name())
405	    }
406	}
