603	impl Eval for ast::Closure<'_> {
604	    type Output = Value;
605	
606	    fn eval(self, vm: &mut Vm) -> SourceResult<Self::Output> {
607	        // Evaluate default values of named parameters.
608	        let mut defaults = Vec::new();
609	        for param in self.params().children() {
610	            if let ast::Param::Named(named) = param {
611	                defaults.push(named.expr().eval(vm)?);
612	            }
613	        }
614	
615	        // Collect captured variables.
616	        let captured = {
617	            let mut visitor = CapturesVisitor::new(Some(&vm.scopes), Capturer::Function);
618	            visitor.visit(self.to_untyped());
619	            visitor.finish()
620	        };
621	
622	        // Define the closure.
623	        let closure = Closure {
624	            node: ClosureNode::Closure(self.to_untyped().clone()),
625	            defaults,
626	            captured,
627	            num_pos_params: self
628	                .params()
629	                .children()
630	                .filter(|p| matches!(p, ast::Param::Pos(_)))
631	                .count(),
632	            params_span: self.params().span(),
633	        };
634	
635	        Ok(Value::Func(Func::from(closure).spanned(self.span())))
636	    }
637	}
