639	/// Call the function in the context with the arguments.
640	#[comemo::memoize]
641	#[expect(clippy::too_many_arguments)]
642	pub fn eval_closure(
643	    func: &Func,
644	    closure: &LazyHash<Closure>,
645	    world: Tracked<dyn World + '_>,
646	    library: &LazyHash<Library>,
647	    introspector: Tracked<dyn Introspector + '_>,
648	    traced: Tracked<Traced>,
649	    sink: TrackedMut<Sink>,
650	    route: Tracked<Route>,
651	    context: Tracked<Context>,
652	    mut args: Args,
653	) -> SourceResult<Value> {
654	    let (name, params, body) = match closure.node {
655	        ClosureNode::Closure(ref node) => {
656	            let closure =
657	                node.cast::<ast::Closure>().expect("node to be an `ast::Closure`");
658	            (closure.name(), closure.params(), closure.body())
659	        }
660	        ClosureNode::Context(ref node) => {
661	            (None, ast::Params::placeholder(), node.cast().unwrap())
662	        }
663	    };
664	
665	    // Don't leak the scopes from the call site. Instead, we use the scope
666	    // of captured variables we collected earlier.
667	    let mut scopes = Scopes::new(None);
668	    scopes.top = closure.captured.clone();
669	
670	    // Prepare the engine.
671	    let introspector = Protected::from_raw(introspector);
672	    let engine = Engine {
673	        library,
674	        world,
675	        introspector,
676	        traced,
677	        sink,
678	        route: Route::extend(route),
679	    };
680	
681	    // Prepare VM.
682	    let mut vm = Vm::new(engine, context, scopes, body.span());
683	
684	    // Provide the closure itself for recursive calls.
685	    if let Some(name) = name {
686	        vm.define(name, func.clone());
687	    }
688	
689	    let num_pos_args = args.to_pos().len();
690	    let sink_size = num_pos_args.checked_sub(closure.num_pos_params);
691	
692	    let mut sink = None;
693	    let mut sink_pos_values = None;
694	    let mut defaults = closure.defaults.iter();
695	    for p in params.children() {
696	        match p {
697	            ast::Param::Pos(pattern) => match pattern {
698	                ast::Pattern::Normal(ast::Expr::Ident(ident)) => {
699	                    vm.define(ident, args.expect::<Value>(&ident)?);
700	                }
701	                pattern => {
702	                    crate::destructure(
703	                        &mut vm,
704	                        pattern,
705	                        args.expect::<Value>("pattern parameter")?,
706	                    )?;
707	                }
708	            },
709	            ast::Param::Spread(spread) => {
710	                sink = Some(spread.sink_ident());
711	                if let Some(sink_size) = sink_size {
712	                    sink_pos_values = Some(args.consume(sink_size)?);
713	                }
714	            }
715	            ast::Param::Named(named) => {
716	                let name = named.name();
717	                let default = defaults.next().unwrap();
718	                let value =
719	                    args.named::<Value>(&name)?.unwrap_or_else(|| default.clone());
720	                vm.define(name, value);
721	            }
722	        }
723	    }
724	
725	    if let Some(sink) = sink {
726	        // Remaining args are captured regardless of whether the sink is named.
727	        let mut remaining_args = args.take();
728	        if let Some(sink_name) = sink {
729	            if let Some(sink_pos_values) = sink_pos_values {
730	                remaining_args.items.extend(sink_pos_values);
731	            }
732	            vm.define(sink_name, remaining_args);
733	        }
734	    }
735	
736	    // Ensure all arguments have been used.
737	    args.finish()?;
738	
739	    // Handle control flow.
740	    let output = body.eval(&mut vm)?;
741	    match vm.flow {
742	        Some(FlowEvent::Return(_, Some(explicit), _)) => return Ok(explicit),
743	        Some(FlowEvent::Return(_, None, _)) => {}
744	        Some(flow) => bail!(flow.forbidden()),
745	        None => {}
746	    }
747	
748	    Ok(output)
749	}
