18	/// Captured arguments to a function.
19	///
20	/// Arguments are either _positional_ or _named,_ and can be accessed through
21	/// the @arguments.pos[`pos`], @arguments.named[`named`], and
22	/// @arguments.at[`at`] methods.
23	///
24	/// Additionally, named arguments can be accessed with @arguments.at[field
25	/// syntax] similar to @dictionary[dictionaries].
26	///
27	/// = Argument Sinks <argument-sinks>
28	/// Like built-in functions, custom functions can also take a variable number of
29	/// arguments. You can specify an _argument sink_ which collects all excess
30	/// arguments as `{..sink}`. The resulting `sink` value is of the `arguments`
31	/// type. It exposes methods to access the positional and named arguments.
32	///
33	/// ```example
34	/// #let format(title, ..authors) = {
35	///   let by = authors
36	///     .pos()
37	///     .join(", ", last: " and ")
38	///
39	///   [= #title]
40	///   text(style: "italic")[By #by]
41	/// }
42	///
43	/// #format("ArtosFlow", "Jane", "Joe")
44	/// ```
45	///
46	/// = Spreading <spreading>
47	/// Inversely to an argument sink, you can _spread_ arguments, arrays and
48	/// dictionaries into a function call with the `{..spread}` operator.
49	///
50	/// ```example
51	/// #let array = (2, 3, 5)
52	/// #calc.min(..array)
53	/// #let dict = (fill: blue)
54	/// #text(..dict)[Hello]
55	/// ```
56	#[ty(scope, cast, name = "arguments", since = "forever")]
57	#[derive(Clone, Hash)]
58	pub struct Args {
59	    /// The callsite span for the function. This is not the span of the argument
60	    /// list itself, but of the whole function call.
61	    pub span: Span,
62	    /// The positional and named arguments.
63	    pub items: EcoVec<Arg>,
64	}
