66	impl Args {
67	    /// Create positional arguments from a span and values.
68	    pub fn new<T: IntoValue>(span: Span, values: impl IntoIterator<Item = T>) -> Self {
69	        let items = values
70	            .into_iter()
71	            .map(|value| Arg {
72	                span,
73	                name: None,
74	                value: Spanned::new(value.into_value(), span),
75	            })
76	            .collect();
77	        Self { span, items }
78	    }
79	
80	    /// Attach a span to these arguments if they don't already have one.
81	    pub fn spanned(mut self, span: Span) -> Self {
82	        if self.span.is_detached() {
83	            self.span = span;
84	        }
85	        self
86	    }
87	
88	    /// Returns the number of remaining positional arguments.
89	    pub fn remaining(&self) -> usize {
90	        self.items.iter().filter(|slot| slot.name.is_none()).count()
91	    }
92	
93	    /// Insert a positional argument at a specific index.
94	    pub fn insert(&mut self, index: usize, span: Span, value: Value) {
95	        self.items.insert(
96	            index,
97	            Arg {
98	                span: self.span,
99	                name: None,
100	                value: Spanned::new(value, span),
101	            },
102	        );
103	    }
104	
105	    /// Push a positional argument.
106	    pub fn push(&mut self, span: Span, value: Value) {
107	        self.items.push(Arg {
108	            span: self.span,
109	            name: None,
110	            value: Spanned::new(value, span),
111	        });
112	    }
113	
114	    /// Consume and cast the first positional argument if there is one.
115	    pub fn eat<T>(&mut self) -> SourceResult<Option<T>>
116	    where
117	        T: FromValue<Spanned<Value>>,
118	    {
119	        for (i, slot) in self.items.iter().enumerate() {
120	            if slot.name.is_none() {
121	                let value = self.items.remove(i).value;
122	                let span = value.span;
123	                return T::from_value(value).at(span).map(Some);
124	            }
125	        }
126	        Ok(None)
127	    }
128	
129	    /// Consume n positional arguments if possible.
130	    pub fn consume(&mut self, n: usize) -> SourceResult<Vec<Arg>> {
131	        let mut list = vec![];
132	
133	        let mut i = 0;
134	        while i < self.items.len() && list.len() < n {
135	            if self.items[i].name.is_none() {
136	                list.push(self.items.remove(i));
137	            } else {
138	                i += 1;
139	            }
140	        }
141	
142	        if list.len() < n {
143	            bail!(self.span, "not enough arguments");
144	        }
145	
146	        Ok(list)
147	    }
148	
149	    /// Consume and cast the first positional argument.
150	    ///
151	    /// Returns a `missing argument: {what}` error if no positional argument is
152	    /// left.
153	    pub fn expect<T>(&mut self, what: &str) -> SourceResult<T>
154	    where
155	        T: FromValue<Spanned<Value>>,
156	    {
157	        match self.eat()? {
158	            Some(v) => Ok(v),
159	            None => bail!(self.missing_argument(what)),
160	        }
161	    }
162	
163	    /// The error message for missing arguments.
164	    fn missing_argument(&self, what: &str) -> SourceDiagnostic {
165	        for item in &self.items {
166	            if let Some(name) = item.name.as_deref()
167	                && name == what
168	            {
169	                return error!(
170	                    item.span,
171	                    "the argument `{what}` is positional";
172	                    hint: "try removing `{name}:`";
173	                );
174	            }
175	        }
176	
177	        error!(self.span, "missing argument: {what}")
178	    }
179	
180	    /// Find and consume the first castable positional argument.
181	    pub fn find<T>(&mut self) -> SourceResult<Option<T>>
182	    where
183	        T: FromValue<Spanned<Value>>,
184	    {
185	        for (i, slot) in self.items.iter().enumerate() {
186	            if slot.name.is_none() && T::castable(&slot.value.v) {
187	                let value = self.items.remove(i).value;
188	                let span = value.span;
189	                return T::from_value(value).at(span).map(Some);
190	            }
191	        }
192	        Ok(None)
193	    }
194	
195	    /// Find and consume all castable positional arguments.
196	    pub fn all<T>(&mut self) -> SourceResult<Vec<T>>
197	    where
198	        T: FromValue<Spanned<Value>>,
199	    {
200	        let mut list = vec![];
201	        let mut errors = eco_vec![];
202	        self.items.retain(|item| {
203	            if item.name.is_some() {
204	                return true;
205	            }
206	            let span = item.value.span;
207	            let spanned = Spanned::new(std::mem::take(&mut item.value.v), span);
208	            match T::from_value(spanned).at(span) {
209	                Ok(val) => list.push(val),
210	                Err(diags) => errors.extend(diags),
211	            }
212	            false
213	        });
214	        if !errors.is_empty() {
215	            return Err(errors);
216	        }
217	        Ok(list)
218	    }
219	
220	    /// Cast and remove the value for the given named argument, returning an
221	    /// error if the conversion fails.
222	    pub fn named<T>(&mut self, name: &str) -> SourceResult<Option<T>>
223	    where
224	        T: FromValue<Spanned<Value>>,
225	    {
226	        // We don't quit once we have a match because when multiple matches
227	        // exist, we want to remove all of them and use the last one.
228	        let mut i = 0;
229	        let mut found = None;
230	        while i < self.items.len() {
231	            if self.items[i].name.as_deref() == Some(name) {
232	                let value = self.items.remove(i).value;
233	                let span = value.span;
234	                found = Some(T::from_value(value).at(span)?);
235	            } else {
236	                i += 1;
237	            }
238	        }
239	        Ok(found)
240	    }
241	
242	    /// Same as named, but with fallback to find.
243	    pub fn named_or_find<T>(&mut self, name: &str) -> SourceResult<Option<T>>
244	    where
245	        T: FromValue<Spanned<Value>>,
246	    {
247	        match self.named(name)? {
248	            Some(value) => Ok(Some(value)),
249	            None => self.find(),
250	        }
251	    }
252	
253	    /// Take out all arguments into a new instance.
254	    pub fn take(&mut self) -> Self {
255	        Self {
256	            span: self.span,
257	            items: std::mem::take(&mut self.items),
258	        }
259	    }
260	
261	    /// Return an "unexpected argument" error if there is any remaining
262	    /// argument.
263	    pub fn finish(self) -> SourceResult<()> {
264	        if let Some(arg) = self.items.first() {
265	            match &arg.name {
266	                Some(name) => bail!(arg.span, "unexpected argument: {name}"),
267	                _ => bail!(arg.span, "unexpected argument"),
268	            }
269	        }
270	        Ok(())
271	    }
272	}
