288	impl Args {
289	    /// Tests whether there is no positional nor named argument.
290	    pub fn is_empty(&self) -> bool {
291	        self.items.is_empty()
292	    }
293	
294	    fn get(&self, key: &ArgumentKey) -> Option<&Value> {
295	        let item = match key {
296	            &ArgumentKey::Index(index) => {
297	                let mut iter = self.items.iter().filter(|item| item.name.is_none());
298	                if index < 0 {
299	                    let index = (-(index + 1)).try_into().ok()?;
300	                    iter.nth_back(index)
301	                } else {
302	                    let index = index.try_into().ok()?;
303	                    iter.nth(index)
304	                }
305	            }
306	            // Accept the last argument with the right name.
307	            ArgumentKey::Name(name) => {
308	                self.items.iter().rfind(|item| item.name.as_ref() == Some(name))
309	            }
310	        };
311	        item.map(|item| &item.value.v)
312	    }
313	
314	    /// Access a named argument as a field.
315	    pub fn field(&self, field: &str) -> StrResult<&Value> {
316	        self.items
317	            .iter()
318	            .rfind(|item| item.name.as_ref().map(|name| name.as_str()) == Some(field))
319	            .ok_or_else(|| eco_format!("no named argument {}", field.repr()))
320	            .map(|item| &item.value.v)
321	    }
322	}
