452	    /// passed function.
453	    ///
454	    /// ```example
455	    /// #{
456	    ///   arguments(0, a: 1, 2)
457	    ///     .map(v => v + 1)
458	    /// }
459	    /// ```
460	    #[func(since = "0.15.0")]
461	    pub fn map(
462	        self,
463	        engine: &mut Engine,
464	        context: Tracked<Context>,
465	        /// The function to apply to each value.
466	        mapper: Spanned<Func>,
467	    ) -> SourceResult<Args> {
468	        self.into_iter()
469	            .map(|arg| {
470	                let mapped_value = mapper.call(engine, context, [arg.value.v])?;
471	                Ok(Arg {
472	                    span: arg.span,
473	                    name: arg.name,
474	                    value: Spanned::detached(mapped_value),
475	                })
476	            })
477	            .collect()
478	    }
