166	/// Call a function.
167	fn call_func(vm: &mut Vm, func: Func, args: Args, span: Span) -> SourceResult<Value> {
168	    let func = func.spanned(span);
169	    let f = || func.call(&mut vm.engine, vm.context, args, span);
170	
171	    // Stacker is broken on WASM.
172	    #[cfg(target_arch = "wasm32")]
173	    return f();
174	
175	    #[cfg(not(target_arch = "wasm32"))]
176	    stacker::maybe_grow(32 * 1024, 2 * 1024 * 1024, f)
177	}
