211	/// The kind of callee in a field-access function call.
212	enum FieldCallee {
213	    /// A method on a type or on content, with the target value to be added as
214	    /// the first argument of the call.
215	    Method(Func, Value),
216	    /// A plain function to call.
217	    Func(Func),
218	    /// The field access doesn't actually produce a function. This will error in
219	    /// code, but not in math.
220	    NonFunc(Value, HintedString),
221	}
222	
223	/// Evaluate a field-access callee, prioritizing associated functions of the
224	/// value's type, "methods", over fields on the specific value.
225	///
226	/// Calls to fields of a value are only allowed for functions (`assert.eq`),
227	/// types (`str.to-unicode`, `table.cell`), modules (`pdf.attach`), and symbols
228	/// (`arrow.l`).
229	///
230	/// In particular, calls to a field function are not allowed for dictionaries
231	/// because it would be ambiguous. If we did allow it, we would either have to
232	/// prioritize methods or field functions, but both choices are bad:
233	/// - Prioritizing methods would make all new method additions breaking changes.
234	/// - Prioritizing field functions would break methods for certain dictionaries,
235	///   e.g. `(at: x => ...).at(key)`.
236	fn eval_field_callee(
237	    vm: &mut Vm,
238	    access: &SyntaxNode,
239	    field: &str,
240	    field_span: Span,
241	    target: Value,
242	    in_math: bool,
243	) -> SourceResult<FieldCallee> {
244	    let guard = vm.engine.binding_guard(field_span);
245	
246	    let mut is_method_call = false;
247	    let callee_value = if let Some(method) = target.ty().scope().get(field) {
248	        is_method_call = true;
249	        let ty = target.ty().short_name();
250	        method
251	            .read(guard)
252	            .or_cannot(format_args!("call method `{field}` on {ty}"))
253	            .at(field_span)?
254	            .clone()
255	    } else if let Value::Content(content) = &target
256	        && let Some(method) = content.elem().scope().get(field)
257	    {
258	        is_method_call = true;
259	        method
260	            .read(guard)
261	            .or_cannot(format_args!("call method `{field}` on content"))
262	            .at(field_span)?
263	            .clone()
264	    } else if matches!(target, Value::Symbol(_) | Value::Type(_) | Value::Module(_)) {
265	        // These types are allowed to use field call syntax on non-methods.
266	        target.field(field, guard).at(field_span)?
267	    } else if let Value::Func(func) = &target {
268	        // Functions can also use field call syntax on non-methods, but not for
269	        // settable fields accessed from context.
270	        match target.field(field, guard).at(field_span) {
271	            Ok(callee_value) => callee_value,
272	            Err(err) => {
273	                if let Some(element) = func.to_element()
274	                    && let Some(field_accessor) = element.settable_field_accessor(field)
275	                {
276	                    let styles = vm.context.styles().at(field_span)?;
277	                    let callee_value = field_accessor(styles);
278	                    bail!(disallowed_field_call_error(
279	                        callee_value,
280	                        access,
281	                        field,
282	                        target,
283	                        in_math
284	                    ));
285	                } else {
286	                    return Err(err);
287	                }
288	            }
289	        }
290	    } else {
291	        // Otherwise we are not allowed to call the field and produce an error.
292	        match target.field(field, guard) {
293	            // The field does exist.
294	            Ok(callee_value) => {
295	                bail!(disallowed_field_call_error(
296	                    callee_value,
297	                    access,
298	                    field,
299	                    target,
300	                    in_math
301	                ));
302	            }
303	            // The field does not exist. We don't try as hard on the error here
304	            // to avoid assuming the user's intent.
305	            Err(_) => {
306	                let (kind, name) = element_or_type_with_name(&target);
307	                bail!(access.span(), "{kind} {name} has no method `{field}`");
308	            }
309	        }
310	    };
311	
312	    vm.trace_at(access.span(), &callee_value);
313	
314	    match callee_value.clone().cast::<Func>() {
315	        Ok(func) if is_method_call => Ok(FieldCallee::Method(func, target)),
316	        Ok(func) => Ok(FieldCallee::Func(func)),
317	        Err(err) => Ok(FieldCallee::NonFunc(callee_value, err)),
318	    }
319	}
