321	/// Produce an error for calls to fields that do exist, but are not allowed to
322	/// be called with field-access syntax.
323	///
324	/// The types that do allow direct field-access calling are `Symbol`, `Type`,
325	/// `Module`, and `Func`. Although functions don't allow settable fields
326	/// accessed from context (like `heading.numbering`) to be called directly.
327	///
328	/// The main types that allow field-access but disallow calling are `Dict`,
329	/// named `Args`, and `Content`.
330	///
331	/// And the remaining types/fields that could produce this error are:
332	/// - `Alignment`: `.x`, `.y`
333	/// - `Length`: `.abs`, `.em`
334	/// - `Rel`: `.ratio`, `.length`
335	/// - `Stroke`: `.cap`, `.dash`, `.join`, `.miter-limit`, `.paint`, `.thickness`
336	/// - `Version`: `.major`, `.minor`, `.patch`
337	fn disallowed_field_call_error(
338	    callee_value: Value,
339	    access: &SyntaxNode,
340	    field: &str,
341	    target: Value,
342	    in_math: bool,
343	) -> SourceDiagnostic {
344	    let is_dict = matches!(target, Value::Dict(_));
345	    let is_named = matches!(target, Value::Args(_));
346	    let mut err = if is_dict {
347	        // Dictionaries get a specific error & hint because they're the easiest
348	        // to attempt this with, and users need to be told directly why it's not
349	        // allowed.
350	        error!(access.span(), "cannot directly call dictionary keys as functions")
351	    } else if is_named {
352	        // Also give the custom error & hint for named arguments.
353	        error!(access.span(), "cannot directly call named argument fields as functions")
354	    } else {
355	        let (kind, name) = element_or_type_with_name(&target);
356	        error!(access.span(), "`{field}` is not a valid method for {kind} `{name}`")
357	    };
358	
359	    if callee_value.clone().cast::<Func>().is_ok() {
360	        err.hint(eco_format!(
361	            "to call the stored function, {}wrap the field access \
362	                in parentheses: `{}({})(..)`",
363	            if in_math { "use code mode and " } else { "" },
364	            if in_math { "#" } else { "" },
365	            access.full_text(),
366	        ));
367	    } else if in_math {
368	        err.hint("try adding a space before the parentheses");
369	    } else {
370	        err.hint(eco_format!(
371	            "to access the `{field}` {}, remove the function arguments: `{}`",
372	            if is_dict {
373	                "key"
374	            } else if is_named {
375	                "argument"
376	            } else {
377	                "field"
378	            },
379	            access.full_text(),
380	        ));
381	    }
382	
383	    if is_dict {
384	        err.hint(
385	            "dictionary keys cannot be used with method syntax as keys could conflict \
386	                with built-in method names",
387	        );
388	    } else if is_named {
389	        err.hint(
390	            "named arguments cannot be used with method syntax as argument names could \
391	                conflict with built-in method names",
392	        );
393	    }
394	
395	    err
396	}
