408	impl Eval for ast::Args<'_> {
409	    type Output = Args;
410	
411	    fn eval(self, vm: &mut Vm) -> SourceResult<Self::Output> {
412	        let mut items = EcoVec::with_capacity(self.items().count());
413	
414	        for arg in self.items() {
415	            let span = arg.span();
416	            match arg {
417	                ast::Arg::Pos(expr) => {
418	                    items.push(Arg {
419	                        span,
420	                        name: None,
421	                        value: Spanned::new(expr.eval(vm)?, expr.span()),
422	                    });
423	                }
424	                ast::Arg::Named(named) => {
425	                    let expr = named.expr();
426	                    items.push(Arg {
427	                        span,
428	                        name: Some(named.name().get().clone().into()),
429	                        value: Spanned::new(expr.eval(vm)?, expr.span()),
430	                    });
431	                }
432	                ast::Arg::Spread(spread) => match spread.expr().eval(vm)? {
433	                    Value::None => {}
434	                    Value::Array(array) => {
435	                        items.extend(array.into_iter().map(|value| Arg {
436	                            span,
437	                            name: None,
438	                            value: Spanned::new(value, span),
439	                        }));
440	                    }
441	                    Value::Dict(dict) => {
442	                        items.extend(dict.into_iter().map(|(key, value)| Arg {
443	                            span,
444	                            name: Some(key),
445	                            value: Spanned::new(value, span),
446	                        }));
447	                    }
448	                    Value::Args(args) => items.extend(args.items),
449	                    v => bail!(spread.span(), "cannot spread {}", v.ty()),
450	                },
451	            }
452	        }
453	
454	        // We do *not* use the `self.span()` here because we want the callsite
455	        // span to be one level higher (the whole function call).
456	        Ok(Args { span: Span::detached(), items })
457	    }
458	}
