460	impl Eval for ast::MathArgs<'_> {
461	    type Output = Args;
462	
463	    fn eval(self, vm: &mut Vm) -> SourceResult<Self::Output> {
464	        // Math args need to fully separate named/pos to handle two-dimensional
465	        // args correctly, for example: `mat(a, delim:"[", b; c, d)`.
466	        let mut named = EcoVec::new();
467	        let mut pos = Vec::new();
468	        let mut two_dim_start: Option<usize> = None;
469	
470	        /// Optimize two-dimensional args by using `pos` as the sole container
471	        /// while iterating and only group into an array when we encounter a
472	        /// semicolon.
473	        fn drain_into_array(pos: &mut Vec<Arg>, start: usize, span: Span) {
474	            let array = pos.drain(start..).map(|arg| arg.value.v).collect();
475	            pos.push(Arg {
476	                span,
477	                name: None,
478	                value: Spanned::new(Value::Array(array), span),
479	            });
480	        }
481	
482	        for ast::MathArg { arg, ends_in_semicolon } in self.arg_items() {
483	            let span = arg.span();
484	            match arg {
485	                ast::Arg::Pos(expr) => {
486	                    pos.push(Arg {
487	                        span,
488	                        name: None,
489	                        value: Spanned::new(expr.eval(vm)?, expr.span()),
490	                    });
491	                }
492	                ast::Arg::Named(named_arg) => {
493	                    let expr = named_arg.expr();
494	                    named.push(Arg {
495	                        span,
496	                        name: Some(named_arg.name().get().clone().into()),
497	                        value: Spanned::new(expr.eval(vm)?, expr.span()),
498	                    });
499	                }
500	                ast::Arg::Spread(spread) => match spread.expr().eval(vm)? {
501	                    Value::None => {}
502	                    Value::Array(array) => {
503	                        pos.extend(array.into_iter().map(|value| Arg {
504	                            span,
505	                            name: None,
506	                            value: Spanned::new(value, span),
507	                        }));
508	                    }
509	                    Value::Dict(dict) => {
510	                        named.extend(dict.into_iter().map(|(key, value)| Arg {
511	                            span,
512	                            name: Some(key),
513	                            value: Spanned::new(value, span),
514	                        }));
515	                    }
516	                    Value::Args(args) => {
517	                        for arg in args.items {
518	                            if arg.name.is_none() {
519	                                pos.push(arg);
520	                            } else {
521	                                named.push(arg);
522	                            }
523	                        }
524	                    }
525	                    v => bail!(spread.span(), "cannot spread {}", v.ty()),
526	                },
527	            }
528	            if ends_in_semicolon {
529	                let start = two_dim_start.unwrap_or(0);
530	                // There's not really a better span to use :/
531	                drain_into_array(&mut pos, start, self.span());
532	                two_dim_start = Some(pos.len());
533	            }
534	        }
535	
536	        if let Some(start) = two_dim_start
537	            && start != pos.len()
538	        {
539	            drain_into_array(&mut pos, start, self.span());
540	        }
541	
542	        named.extend(pos);
543	        Ok(Args { span: Span::detached(), items: named })
544	    }
545	}
