547	/// For non-functions in math, we evaluate the arguments and punctuation as
548	/// content and wrap in an [`LrElem`].
549	fn unparse_math_args(
550	    vm: &mut Vm,
551	    args: ast::MathArgs,
552	    callee: ast::MathAccess,
553	) -> SourceResult<Content> {
554	    let mut body = Vec::new();
555	    let mut errors = EcoVec::new();
556	    for item in args.content_items() {
557	        match item {
558	            ast::MathArgItem::Space(space) => {
559	                body.push(space.eval(vm)?.spanned(space.span()));
560	            }
561	            ast::MathArgItem::Comma(c, node)
562	            | ast::MathArgItem::Semicolon(c, node)
563	            | ast::MathArgItem::LeftParen(c, node)
564	            | ast::MathArgItem::RightParen(c, node) => {
565	                body.push(SymbolElem::packed(c).spanned(node.span()));
566	            }
567	            ast::MathArgItem::Arg(ast::Arg::Pos(expr)) => {
568	                // We use `Value::display` to convert argument expressions into
569	                // content instead of `Content::from_value`. This makes it so we
570	                // don't error on `$sin(#1)$` because we don't error on `$#1$`.
571	                body.push(expr.eval(vm)?.display().spanned(expr.span()));
572	            }
573	            ast::MathArgItem::Arg(ast::Arg::Named(named)) => {
574	                let name = callee.to_untyped().full_text();
575	                let fixed = named.to_untyped().full_text().replacen(":", "\\:", 1);
576	                errors.push(error!(
577	                    named.span(), "named-argument syntax can only be used with functions";
578	                    hint[callee.span()]: "`{name}` is not a function";
579	                    hint: "to render the colon as text, escape it: `{fixed}`";
580	                ));
581	            }
582	            ast::MathArgItem::Arg(ast::Arg::Spread(spread)) => {
583	                let name = callee.to_untyped().full_text();
584	                let fixed = spread.to_untyped().full_text().replacen("..", ".. ", 1);
585	                errors.push(error!(
586	                    spread.span(), "spread-argument syntax can only be used with functions";
587	                    hint[callee.span()]: "`{name}` is not a function";
588	                    hint: "to render the dots as text, add a space: `{fixed}`";
589	                ));
590	            }
591	        }
592	    }
593	
594	    if !errors.is_empty() {
595	        return Err(errors);
596	    }
597	
598	    Ok(LrElem::new(SequenceElem::new(body).pack())
599	        .pack()
600	        .spanned(args.span()))
601	}
