751	/// A visitor that determines which variables to capture for a closure.
752	pub struct CapturesVisitor<'a> {
753	    external: Option<&'a Scopes<'a>>,
754	    internal: Scopes<'a>,
755	    captures: Scope,
756	    capturer: Capturer,
757	}
758	
759	impl<'a> CapturesVisitor<'a> {
760	    /// Create a new visitor for the given external scopes.
761	    pub fn new(external: Option<&'a Scopes<'a>>, capturer: Capturer) -> Self {
762	        Self {
763	            external,
764	            internal: Scopes::new(None),
765	            captures: Scope::new(),
766	            capturer,
767	        }
768	    }
769	
770	    /// Return the scope of captured variables.
771	    pub fn finish(self) -> Scope {
772	        self.captures
773	    }
774	
775	    /// Visit any node and collect all captured variables.
776	    pub fn visit(&mut self, node: &SyntaxNode) {
777	        match node.cast() {
778	            // Every identifier is a potential variable that we need to capture.
779	            // Identifiers that shouldn't count as captures because they
780	            // actually bind a new name are handled below (individually through
781	            // the expressions that contain them).
782	            Some(ast::Expr::Ident(ident)) => {
783	                self.capture(ident.get(), Scopes::get_binding);
784	            }
785	            Some(ast::Expr::MathIdent(ident)) => {
786	                self.capture(ident.get(), Scopes::get_binding_in_math);
787	            }
788	
789	            // Code and content blocks create a scope.
790	            Some(ast::Expr::CodeBlock(_) | ast::Expr::ContentBlock(_)) => {
791	                self.internal.enter();
792	                for child in node.children() {
793	                    self.visit(child);
794	                }
795	                self.internal.exit();
796	            }
797	
798	            // Don't capture the field of a field access.
799	            Some(ast::Expr::FieldAccess(access)) => {
800	                self.visit(access.target().to_untyped());
801	            }
802	            Some(ast::Expr::MathFieldAccess(access)) => {
803	                self.visit(access.target().to_untyped());
804	            }
805	
806	            // A closure contains parameter bindings, which are bound before the
807	            // body is evaluated. Care must be taken so that the default values
808	            // of named parameters cannot access previous parameter bindings.
809	            Some(ast::Expr::Closure(expr)) => {
810	                for param in expr.params().children() {
811	                    if let ast::Param::Named(named) = param {
812	                        self.visit(named.expr().to_untyped());
813	                    }
814	                }
815	
816	                self.internal.enter();
817	                if let Some(name) = expr.name() {
818	                    self.bind(name);
819	                }
820	
821	                for param in expr.params().children() {
822	                    match param {
823	                        ast::Param::Pos(pattern) => {
824	                            for ident in pattern.bindings() {
825	                                self.bind(ident);
826	                            }
827	                        }
828	                        ast::Param::Named(named) => self.bind(named.name()),
829	                        ast::Param::Spread(spread) => {
830	                            if let Some(ident) = spread.sink_ident() {
831	                                self.bind(ident);
832	                            }
833	                        }
834	                    }
835	                }
836	
837	                self.visit(expr.body().to_untyped());
838	                self.internal.exit();
839	            }
840	
841	            // A let expression contains a binding, but that binding is only
842	            // active after the body is evaluated.
843	            Some(ast::Expr::LetBinding(expr)) => {
844	                if let Some(init) = expr.init() {
845	                    self.visit(init.to_untyped());
846	                }
847	
848	                for ident in expr.kind().bindings() {
849	                    self.bind(ident);
850	                }
851	            }
852	
853	            // A for loop contains one or two bindings in its pattern. These are
854	            // active after the iterable is evaluated but before the body is
855	            // evaluated.
856	            Some(ast::Expr::ForLoop(expr)) => {
857	                self.visit(expr.iterable().to_untyped());
858	                self.internal.enter();
859	
860	                let pattern = expr.pattern();
861	                for ident in pattern.bindings() {
862	                    self.bind(ident);
863	                }
864	
865	                self.visit(expr.body().to_untyped());
866	                self.internal.exit();
867	            }
868	
869	            // An import contains items, but these are active only after the
870	            // path is evaluated.
871	            Some(ast::Expr::ModuleImport(expr)) => {
872	                self.visit(expr.source().to_untyped());
873	                if let Some(ast::Imports::Items(items)) = expr.imports() {
874	                    for item in items.iter() {
875	                        self.bind(item.bound_name());
876	                    }
877	                }
878	            }
879	
880	            _ => {
881	                // Never capture the name part of a named pair.
882	                if let Some(named) = node.cast::<ast::Named>() {
883	                    self.visit(named.expr().to_untyped());
884	                    return;
885	                }
886	
887	                // Everything else is traversed from left to right.
888	                for child in node.children() {
889	                    self.visit(child);
890	                }
891	            }
892	        }
893	    }
894	
895	    /// Bind a new internal variable.
896	    fn bind(&mut self, ident: ast::Ident) {
897	        // The concrete value does not matter as we only use the scoping
898	        // mechanism of `Scopes`, not the values themselves.
899	        self.internal
900	            .top
901	            .bind(ident.get().clone(), Binding::detached(Value::None));
902	    }
903	
904	    /// Capture a variable if it isn't internal.
905	    fn capture(
906	        &mut self,
907	        ident: &EcoString,
908	        getter: impl FnOnce(&'a Scopes<'a>, &str) -> HintedStrResult<&'a Binding>,
909	    ) {
910	        if self.internal.get_binding(ident).is_ok() {
911	            return;
912	        }
913	
914	        // If the variable has already been captured, there is no need to look
915	        // it up again, since the external scopes don't change.
916	        if self.captures.get(ident).is_some() {
917	            return;
918	        }
919	
920	        let binding = match self.external {
921	            Some(external) => match getter(external, ident) {
922	                Ok(binding) => binding.capture(self.capturer),
923	                Err(_) => return,
924	            },
925	            // The external scopes are only `None` when we are doing IDE capture
926	            // analysis, in which case the concrete value doesn't matter.
927	            None => Binding::detached(Value::None),
928	        };
929	
930	        self.captures.bind(ident.clone(), binding);
931	    }
932	}
