953	    #[test]
954	    fn test_captures() {
955	        let mut scopes = Scopes::new(None);
956	        scopes.top.define("f", 0);
957	        scopes.top.define("x", 0);
958	        scopes.top.define("y", 0);
959	        scopes.top.define("z", 0);
960	        let s = &scopes;
961	
962	        // Let binding and function definition.
963	        test(s, "#let x = x", &["x"]);
964	        test(s, "#let x; #(x + y)", &["y"]);
965	        test(s, "#let f(x, y) = x + y", &[]);
966	        test(s, "#let f(x, y) = f", &[]);
967	        test(s, "#let f = (x, y) => f", &["f"]);
968	
969	        // Closure with different kinds of params.
970	        test(s, "#((x, y) => x + z)", &["z"]);
971	        test(s, "#((x: y, z) => x + z)", &["y"]);
972	        test(s, "#((..x) => x + y)", &["y"]);
973	        test(s, "#((x, y: x + z) => x + y)", &["x", "z"]);
974	        test(s, "#{x => x; x}", &["x"]);
975	
976	        // Show rule.
977	        test(s, "#show y: x => x", &["y"]);
978	        test(s, "#show y: x => x + z", &["y", "z"]);
979	        test(s, "#show x: x => x", &["x"]);
980	
981	        // For loop.
982	        test(s, "#for x in y { x + z }", &["y", "z"]);
983	        test(s, "#for (x, y) in y { x + y }", &["y"]);
984	        test(s, "#for x in y {} #x", &["x", "y"]);
985	
986	        // Import.
987	        test(s, "#import z: x, y", &["z"]);
988	        test(s, "#import x + y: x, y, z", &["x", "y"]);
989	
990	        // Blocks.
991	        test(s, "#{ let x = 1; { let y = 2; y }; x + y }", &["y"]);
992	        test(s, "#[#let x = 1]#x", &["x"]);
993	
994	        // Field access.
995	        test(s, "#x.y.f(z)", &["x", "z"]);
996	
997	        // Parenthesized expressions.
998	        test(s, "#f(x: 1)", &["f"]);
999	        test(s, "#(x: 1)", &[]);
1000	        test(s, "#(x = 1)", &["x"]);
1001	        test(s, "#(x += y)", &["x", "y"]);
1002	        test(s, "#{ (x, z) = (y, 1) }", &["x", "y", "z"]);
1003	        test(s, "#(x.at(y) = 5)", &["x", "y"]);
1004	    }
