1006	    #[test]
1007	    fn test_captures_in_math() {
1008	        let mut scopes = Scopes::new(None);
1009	        scopes.top.define("f", 0);
1010	        scopes.top.define("x", 0);
1011	        scopes.top.define("y", 0);
1012	        scopes.top.define("z", 0);
1013	        // Multi-letter variables are required for math.
1014	        scopes.top.define("foo", 0);
1015	        scopes.top.define("bar", 0);
1016	        scopes.top.define("x-bar", 0);
1017	        scopes.top.define("x_bar", 0);
1018	        let s = &scopes;
1019	
1020	        // Basic math identifier differences.
1021	        test(s, "$ x f(z) $", &[]); // single letters not captured.
1022	        test(s, "$ #x #f(z) $", &["f", "x", "z"]);
1023	        test(s, "$ foo f(bar) $", &["bar", "foo"]);
1024	        test(s, "$ #foo[#$bar$] $", &["bar", "foo"]);
1025	        test(s, "$ #let foo = x; foo $", &["x"]);
1026	
1027	        // Math idents don't have dashes/underscores
1028	        test(s, "$ x-y x_y foo-x x_bar $", &["bar", "foo"]);
1029	        test(s, "$ #x-bar #x_bar $", &["x-bar", "x_bar"]);
1030	
1031	        // Named-params.
1032	        test(s, "$ foo(bar: y) $", &["foo"]);
1033	        test(s, "$ foo(x-y: 1, bar-z: 2) $", &["foo"]);
1034	
1035	        // Field access in math.
1036	        test(s, "$ foo.bar $", &["foo"]);
1037	        test(s, "$ foo.x $", &["foo"]);
1038	        test(s, "$ x.foo $", &["foo"]);
1039	        test(s, "$ foo . bar $", &["bar", "foo"]);
1040	        test(s, "$ foo.x.y.bar(z) $", &["foo"]);
1041	        test(s, "$ foo.x-bar $", &["bar", "foo"]);
1042	        test(s, "$ foo.x_bar $", &["bar", "foo"]);
1043	        test(s, "$ #x_bar.x-bar $", &["x_bar"]);
1044	    }
1045	}
