296	#[derive(Debug, Clone, PartialEq, PartialOrd, Hash)]
297	pub enum CastInfo {
298	    /// Any value is okay.
299	    Any,
300	    /// A specific value, plus short documentation for that value.
301	    Value(Value, &'static str),
302	    /// Any value of a type.
303	    Type(Type),
304	    /// Multiple alternatives.
305	    Union(Vec<Self>),
306	}
